/** Server-owned, fictional patient information. Never import into a client component.
 * Decomposed only from catalog scenario/findings; author recommendations are not patient facts.
 * Unknown/not-performed entries never imply a normal or negative clinical finding.
 */
export const DISCOVERY_PACK_VERSION = "discovery-2026-10-23.1";
const R = String.raw;
const p = (id: string, topic: string, pattern: string, answer: string): DiscoveryFact => ({ id, channel: "patient", topic, patterns: [pattern], answer });
const e = (id: string, topic: string, pattern: string, answer: string): DiscoveryFact => ({ id, channel: "exam", topic, patterns: [pattern], answer });
const u = (channel: "patient" | "exam", id: string, topic: string, pattern: string, answer?: string): DiscoveryFact => ({ id, channel, topic, patterns: [pattern], answer: answer ?? `${topic} is not specified in this simulated case.`, available: false });
// Case 023 explicitly compares two restorations; keep their findings separate.
const contactCaseTeeth: Record<string, number[]> = {
  history: [30], concern: [30], food: [29, 30], contact: [29, 30], probing: [29, 30],
  percussion: [30], "crown-margins": [30], "adjacent-restoration": [29], "adjacent-contour": [29],
  bitewing: [29, 30], pa: [30], "delivery-record": [30], occlusal: [29, 30], mobility: [29, 30],
};
const pack = (number: number, chiefComplaint: string, facts: DiscoveryFact[]): DiscoveryPatient => {
  const caseId = `drchi-${String(number).padStart(3, "0")}`;
  return { caseId, version: DISCOVERY_PACK_VERSION, chiefComplaint, facts: facts.map(f => ({ ...f, id: `${caseId}:${f.id}`,
    ...(number === 23 && contactCaseTeeth[f.id] ? { toothNumbers: contactCaseTeeth[f.id] } : {}) })) };
};

